/* =====================================================================================

   Teotihuacan Mapping Project (TMP) – DF10 Database (MS Access .accdb → PostgreSQL 17)

   Rudolf Cesaretti
   2025-04-25

   PostgreSQL 17 syntax SQL script to migrate DF10 from MS Access 2010 to PostgreSQL 17.
	As such, this script replicates the DF10 MS Access database authored by Anne
	Sherfield in May of 2022 (DF10.May2022.accdb) with some minor structural changes
	to the schema and translation-based edits to facilitate valid migration.
	Column and table names are preserved verbatim.

   NOTE: Running this script does not create a database. It populates an empty database.

   ===================================================================================== */


-- ============================================================================
--                            CREATE SCHEMA
-- ============================================================================

-- isolate all TMP_DF8 objects in a dedicated `tmp_df10` schema + ensure all unqualified object names resolve into tmp_df10 first

BEGIN;
  CREATE SCHEMA IF NOT EXISTS tmp_df10
    AUTHORIZATION postgres;
  SET search_path = tmp_df10, public;

COMMIT;


--- ====================================================================================
---                            TABLES
--- ====================================================================================

BEGIN;
  SET client_min_messages TO WARNING;      -- keep output tidy
COMMIT;

--- ====================================================================================
---                            TABLES
--- ====================================================================================

/* ---------- Create `provTable` table ------------------------------------------------- */
BEGIN;
CREATE TABLE IF NOT EXISTS tmp_df10."provTable" (
    "SSN"            SMALLINT PRIMARY KEY,
    "Site"           TEXT,
    "Subsite"        TEXT,
    "Unit"           TEXT,
    "Northing"       SMALLINT,
    "Easting"        SMALLINT
);
COMMIT;
/* ---------- Create `archToSSN` table (duplicates allowed) ---------------------------- */
BEGIN;
CREATE TABLE IF NOT EXISTS tmp_df10."archToSSN" (
    "ID"                 SERIAL PRIMARY KEY,             -- new surrogate key
    "ArchPolyID"         SMALLINT,
    "SSN"                SMALLINT,
    "Area_SSN_Coverage"  DOUBLE PRECISION
);

ALTER TABLE tmp_df10."archToSSN"
    ADD CONSTRAINT "fk_archToSSN_SSN"
        FOREIGN KEY ("SSN") REFERENCES tmp_df10."provTable" ("SSN")
        NOT VALID;                                          -- msaccess link not enforced

CREATE INDEX "idx_archToSSN_ArchPolyID_SSN" ON tmp_df10."archToSSN" ("ArchPolyID","SSN");
COMMIT;
/* ---------- Create `artifactCodes` table --------------------------------------------- */
BEGIN;
CREATE TABLE IF NOT EXISTS tmp_df10."artifactCodes" (
    "Code"       SMALLINT PRIMARY KEY,
    "Description"    TEXT
);
COMMIT;
/* ---------- Create `artifactTable` table --------------------------------------------- */
BEGIN;
CREATE TABLE IF NOT EXISTS tmp_df10."artifactTable" (
    "ID"         SERIAL PRIMARY KEY,         --- ID is a newly added field
    "ArtCode1"   SMALLINT,
    "ArtCode2"   SMALLINT,
    "ArtCode3"   SMALLINT,
    "SSN"        SMALLINT NOT NULL
                 REFERENCES tmp_df10."provTable" ("SSN")
                 ON UPDATE CASCADE ON DELETE RESTRICT,
    "Count"      INTEGER,
    "Where"      TEXT
);

ALTER TABLE tmp_df10."artifactTable"
    ADD CONSTRAINT "fk_artifactTable_code1"
        FOREIGN KEY ("ArtCode1") REFERENCES tmp_df10."artifactCodes" ("Code") NOT VALID,
    ADD CONSTRAINT "fk_artifactTable_code2"
        FOREIGN KEY ("ArtCode2") REFERENCES tmp_df10."artifactCodes" ("Code") NOT VALID,
    ADD CONSTRAINT "fk_artifactTable_code3"
        FOREIGN KEY ("ArtCode3") REFERENCES tmp_df10."artifactCodes" ("Code") NOT VALID;

CREATE INDEX "idx_artifactTable_SSN"      ON tmp_df10."artifactTable" ("SSN");
CREATE INDEX "idx_artifactTable_ArtCode1" ON tmp_df10."artifactTable" ("ArtCode1");
CREATE INDEX "idx_artifactTable_ArtCode2" ON tmp_df10."artifactTable" ("ArtCode2");
CREATE INDEX "idx_artifactTable_ArtCode3" ON tmp_df10."artifactTable" ("ArtCode3");
COMMIT;
/* ---------- Create `codeCodes` table ------------------------------------------------- */
BEGIN;
CREATE TABLE IF NOT EXISTS tmp_df10."codeCodes" (
    "Code"        SMALLINT PRIMARY KEY,
    "Description" TEXT
);
COMMIT;
/* ---------- Create `codeTable` table ------------------------------------------------- */
BEGIN;
CREATE TABLE IF NOT EXISTS tmp_df10."codeTable" (
    "ID"         SERIAL PRIMARY KEY,--- ID is a newly added field
    "SSN"        SMALLINT NOT NULL
                 REFERENCES tmp_df10."provTable" ("SSN")
                 ON UPDATE CASCADE ON DELETE RESTRICT,
    "Code"       SMALLINT NOT NULL
                 REFERENCES tmp_df10."codeCodes" ("Code")
                 ON UPDATE CASCADE,
    "Variable"   TEXT,
    "Where"      TEXT
);

CREATE INDEX "idx_codeTable_SSN"  ON tmp_df10."codeTable" ("SSN");
CREATE INDEX "idx_codeTable_Code" ON tmp_df10."codeTable" ("Code");
COMMIT;
/* ---------- Create `interpCodes` table ----------------------------------------------- */
BEGIN;
CREATE TABLE IF NOT EXISTS tmp_df10."interpCodes" (
    "Code"        SMALLINT PRIMARY KEY,
    "Description" TEXT
);
COMMIT;
/* ---------- Create `interpTable` table ----------------------------------------------- */
BEGIN;
CREATE TABLE IF NOT EXISTS tmp_df10."interpTable" (
    "ID"          SERIAL PRIMARY KEY,--- ID is a newly added field
    "SSN"         SMALLINT NOT NULL
                 REFERENCES tmp_df10."provTable" ("SSN")
                 ON UPDATE CASCADE ON DELETE RESTRICT,
    "Code"        SMALLINT,
    "Variable"    TEXT,
    "Where"       TEXT
);

ALTER TABLE tmp_df10."interpTable"
    ADD CONSTRAINT "fk_interpTable_Code"
        FOREIGN KEY ("Code") REFERENCES tmp_df10."interpCodes" ("Code") NOT VALID;

CREATE INDEX "idx_interpTable_SSN"  ON tmp_df10."interpTable" ("SSN");
CREATE INDEX "idx_interpTable_Code" ON tmp_df10."interpTable" ("Code");
COMMIT;
/* ---------- Create `totalsTable` table ----------------------------------------------- */
BEGIN;
CREATE TABLE IF NOT EXISTS tmp_df10."totalsTable" (
    "ID"          SERIAL PRIMARY KEY,--- ID is a newly added field
    "SSN"         SMALLINT NOT NULL
                 REFERENCES tmp_df10."provTable" ("SSN")
                 ON UPDATE CASCADE ON DELETE RESTRICT,
    "Count"       INTEGER,
    "Variable"    TEXT,
    "Where"       TEXT
);

CREATE INDEX "idx_totalsTable_SSN" ON tmp_df10."totalsTable" ("SSN");
COMMIT;

/* ---------- Add foreign key indexes -------------------------------------------------- */

BEGIN;
  CREATE INDEX IF NOT EXISTS idx_archtossn_ssn
    ON tmp_df10."archToSSN"("SSN");
  CREATE INDEX IF NOT EXISTS idx_artifacttable_ssn
    ON tmp_df10."artifactTable"("SSN");
  CREATE INDEX IF NOT EXISTS idx_artifacttable_artcode1
    ON tmp_df10."artifactTable"("ArtCode1");
  CREATE INDEX IF NOT EXISTS idx_artifacttable_artcode2
    ON tmp_df10."artifactTable"("ArtCode2");
  CREATE INDEX IF NOT EXISTS idx_artifacttable_artcode3
    ON tmp_df10."artifactTable"("ArtCode3");
  CREATE INDEX IF NOT EXISTS idx_codetable_ssn
    ON tmp_df10."codeTable"("SSN");
  CREATE INDEX IF NOT EXISTS idx_codetable_code
    ON tmp_df10."codeTable"("Code");
  CREATE INDEX IF NOT EXISTS idx_interptable_ssn
    ON tmp_df10."interpTable"("SSN");
  CREATE INDEX IF NOT EXISTS idx_interptable_code
    ON tmp_df10."interpTable"("Code");
  CREATE INDEX IF NOT EXISTS idx_totalstable_ssn
    ON tmp_df10."totalsTable"("SSN");
COMMIT;

